  'AI চালু থাকলে Anthropic-এ যায়: আপনার বলা বা লেখা বাক্য, টাকার হিসাবের সারাংশ (নাম ও অঙ্ক), রিমাইন্ডার, কাজ, নোট, ওষুধ ও অভ্যাসের নাম, বিশেষ দিন, ডকুমেন্টের নাম আর “মনে রেখো” কথাগুলো — যাতে আপনার জিনিস নিয়ে ঠিক উত্তর দিতে পারে। কখনো যায় না: পাসওয়ার্ড ও ভল্ট, PIN/OTP/পাসওয়ার্ড থাকা নোট, ফোন-কার্ড-NID নম্বর, ইমেইল, স্বাস্থ্যের মাপ আর অন্য অ্যাপের মেসেজ।': 'With the AI on, Anthropic gets: what you say or type, a money summary (names and amounts), reminders, to-dos, notes, medicine and habit names, special days, document names and your “remember” notes — so it can answer about your things. Never sent: passwords and the vault, notes with PINs/OTPs/passwords, phone/card/ID numbers, e-mails, health readings and other apps’ messages.',
  'AI চালু থাকলে আপনার বলা বাক্য, টাকার হিসাবের সারাংশ, রিমাইন্ডার, কাজ আর নোট Anthropic-এ যায়, যাতে আপনার জিনিস নিয়ে প্রশ্নের ঠিক উত্তর দিতে পারে; পাসওয়ার্ড, ভল্ট, PIN, ফোন নম্বর বা গোপন কোড থাকা নোট কখনো যায় না।': 'With AI on, what you say, a summary of your money, reminders, tasks and notes go to Anthropic so it can answer questions about your things correctly; passwords, the vault, PINs, phone numbers or notes with secret codes never go.',
  'AI চালু থাকলে আপনার বলা বাক্য, লেনদেনের মানুষের নাম আর টাকার হিসাবের সারাংশ Anthropic-এ যায়; পাসওয়ার্ড, ভল্ট, PIN, ফোন নম্বর, নোট বা কাজের লেখা যায় না।': 'With AI on, what you say, names of people you deal with and a summary of your money go to Anthropic; passwords, the vault, PINs, phone numbers, notes or task text never go.',
