  'অনেক কিছু পারি — কাজের তালিকা, সময়মতো মনে করানো, ফোন-মেসেজ, ধার-দেনা আর আয়-ব্যয়ের হিসাব, নোট, কাগজপত্র, পাসওয়ার্ড, স্বাস্থ্য আর বিশেষ দিন। যেকোনো পাতাও খুলে দিতে পারি — যেমন বলুন “নোট খোলো”। পুরো তালিকা নিচে দিলাম।': 'Plenty — to-dos, reminders on time, calls and messages, loans and income/spending, notes, papers, passwords, health and special days. I can open any page too — say “নোট খোলো”. The full list is below.',
