  'আপনার জন্মতারিখের কোনো তথ্য নেই। স্বাস্থ্য পাতায় “বদলান” চেপে জন্মতারিখ দিতে পারেন — পরে যেকোনো সময় জিজ্ঞেস করলে উত্তর দেবো।': 'There\'s no date of birth saved. Add it on the Health page (tap Edit), then ask me any time.',
