  'আপনার জেলায় কারো এই গ্রুপের রক্ত লাগলে নোটিফিকেশন পাবেন (দিনে ৩টার বেশি না; রক্ত দেওয়ার ৩ মাসের মধ্যে একটাও না)। শুধু গ্রুপ, জেলা, শেষ দেওয়ার দিন আর নম্বর সার্ভারে থাকে — নম্বর দেখবেন শুধু যাঁকে আপনি রাজি বলবেন।': 'You are told when someone in your district needs your group (at most 3 a day; none within 3 months of giving). Only your group, district, last donation and number are kept on the server — only people you say yes to see your number.',
  'আপনার জেলার যাঁরা দাতা আর এই গ্রুপে দিতে পারেন, তাঁরা নোটিফিকেশন পাবেন এবং আপনার নম্বর দেখবেন। একসাথে ৩টা পর্যন্ত অনুরোধ খোলা রাখা যায়।': 'Donors in your district who can give to this group are notified and see your number. Up to 3 requests can be open at once.',
