  'এক অ্যাকাউন্ট থেকে আরেকটায়': 'From one account to another',
  'এক চান্দ্র বছর ধরে নিসাব পরিমাণ সম্পদ থাকলে মোট সম্পদের ২.৫% যাকাত। এটা আনুমানিক হিসাব — নিশ্চিত হতে আলেমের পরামর্শ নিন।': 'If you have held at least the nisab for a lunar year, zakat is 2.5% of your wealth. This is an estimate — consult a scholar to be sure.',
  'এক চান্দ্র বছর ধরে নিসাব পরিমাণ সম্পদ থাকলে মোট সম্পদের ২.৫% যাকাত। এটা আনুমানিক হিসাব — নিশ্চিত হতে আলেমের পরামর্শ নিন। মুখেও জিজ্ঞেস করা যায়: “আমার যাকাত কত?”': 'With nisab-level wealth held for a lunar year, zakat is 2.5%. This is an estimate — ask a scholar to be sure. You can also ask aloud: “আমার যাকাত কত?”',
