  'একই নামের মানুষ আলাদা রাখতে': 'To keep people with the same name apart',
  'একটা বেছে নিলে তার সব জিনিস কাজের তালিকায় আলাদা নামে উঠে যাবে। টিক দিয়ে দিয়ে শেষ করুন, দরকারমতো বাদ দিন বা যোগ করুন।': 'Pick one and all its items go into your tasks as a list of that name. Tick them off, remove or add as you like.',
