  'এখনো কোনো কাগজপত্র রাখা নেই। ডকুমেন্টস পাতা থেকে ছবি তুলে বা ফাইল দিয়ে রাখতে পারেন।': 'No papers are kept yet. On the Documents page, take a photo or add a file.',
