  'এখনো কোনো ছবি রাখা নেই। ডকুমেন্টস পাতায় ছবি তুলে বা গ্যালারি থেকে রাখতে পারেন।': 'No photos kept yet. Add them on the Documents page — take one or pick from the gallery.',
