  'এখনো কোনো প্রজেক্ট খোলা হয়নি। বলুন, যেমন “রহিম ভবন প্রজেক্টে ৫০ হাজার টাকা এলো”।': 'No project yet. Say e.g. “রহিম ভবন প্রজেক্টে ৫০ হাজার টাকা এলো”.',
