  'এখানে লেখা কথাগুলো সহকারী উত্তর দেওয়ার সময় মনে রাখে। মুখেও বলা যায়: “মনে রেখো, রহিম আমার শ্যালক”। AI চালু থাকলে এগুলো উত্তর তৈরিতে পাঠানো হয়; পাসওয়ার্ড বা গোপন কিছু এখানে লিখবেন না।': 'The assistant keeps these in mind when answering. You can also say: “মনে রেখো, রহিম আমার শ্যালক”. With AI on, these are sent to help answer; never write passwords or secrets here.',
  'এখানে শুধু মাপ রাখা হয়; রোগ নির্ণয় করা হয় না। মাপ স্বাভাবিকের বাইরে গেলে ডাক্তার দেখান। সব তথ্য এই ফোনে তালাবদ্ধ থাকে।': 'This only keeps readings; it does not diagnose. If a reading is out of range, see a doctor. Everything stays locked on this phone.',
