  'মেসেজ পড়া চালু': 'Read messages',
  'মেসেজ পড়া বন্ধ রাখা আছে। উপরের ডান কোণের বোতাম থেকে চালু করুন।': 'Reading messages is off. Turn it on with the button at the top right.',
  'মেসেজ শুধু এই ফোনে থাকে — কোনো সার্ভার বা AI-তে যায় না। OTP, পিন, পাসওয়ার্ডের মেসেজ রাখা হয় না। কোন অ্যাপ পড়বে আপনি বেছে দেবেন, যেকোনো সময় বন্ধ করা যায়। আগের পুরনো চ্যাট পড়া যায় না, শুধু নতুন আসা মেসেজ।': 'Messages stay on this phone — never sent to a server or AI. OTP, PIN and password messages are never kept. You choose which apps it reads and can turn it off any time. Old chats cannot be read, only new messages.',
  'মেসেজগুলো শুধু এই ফোনে, তালাবদ্ধ অবস্থায় থাকে; কোনো সার্ভার বা AI-তে যায় না। OTP, পিন বা পাসওয়ার্ডের মেসেজ রাখা হয় না। ৩০ দিন পর নিজে থেকে মুছে যায়।': 'Messages stay locked on this phone only; they never go to a server or AI. OTP, PIN or password messages are never kept. They are deleted after 30 days.',
